composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      DB_HOST: {{env.DB_HOST}}
      DB_ROOT_PASSWD: {{env.DB_ROOT_PASSWD}}
      SEAFILE_ADMIN_EMAIL: {{env.SEAFILE_ADMIN_EMAIL}}
      SEAFILE_ADMIN_PASSWORD: {{env.SEAFILE_ADMIN_PASSWORD}}
      SEAFILE_SERVER_HOSTNAME: {{env.SEAFILE_SERVER_HOSTNAME}}
      TIME_ZONE: {{env.TZ}}
    volumes:
      - {{appDataPath}}/data:/shared
    depends_on:
      - {{serviceName}}-db
      - {{serviceName}}-memcached
  {{serviceName}}-db:
    image: mariadb:10.11
    container_name: {{serviceName}}-db
    restart: unless-stopped
    environment:
      MYSQL_ROOT_PASSWORD: {{env.DB_ROOT_PASSWD}}
      MYSQL_LOG_CONSOLE: "true"
    volumes:
      - {{appDataPath}}/db:/var/lib/mysql
  {{serviceName}}-memcached:
    image: memcached:1.6-alpine
    container_name: {{serviceName}}-memcached
    restart: unless-stopped
